BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "RouteList" (
	"RouteCode"	INTEGER NOT NULL UNIQUE,
	"RouteNum"	TEXT NOT NULL,
	"RouteDestEng"	TEXT,
	"RouteDestChi"	TEXT,
	"RouteTypeEng"	TEXT,
	"RouteTypeChi"	TEXT,
	"RouteEraNum"	INTEGER,
	"RouteOperator"	TEXT,
	"OpenDataRouteId"	TEXT,
	"RouteViaChi"	TEXT,
	"RouteViaEng"	TEXT,
	"LastViewedDateTime"	INTEGER
);
CREATE TABLE IF NOT EXISTS "LedBinFile" (
	"FileName"	TEXT NOT NULL UNIQUE,
	"FileBinary"	BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS "OperatorList" (
	"OperatorID"	TEXT NOT NULL UNIQUE,
	"OperatorNameChi"	TEXT NOT NULL,
	"OperatorNameEng"	TEXT NOT NULL,
	"RwaChi"	TEXT NOT NULL,
	"RwaEng"	TEXT NOT NULL,
	"OperatorColor"	TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS "BusStopsNamesReplacementsList" (
	"OriginalName"	TEXT NOT NULL UNIQUE,
	"NewShortName"	TEXT NOT NULL,
	"NewLongName"	TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "BusStopsStatistics" (
	"FromLatitude"	TEXT NOT NULL,
	"FromLongitude"	TEXT NOT NULL,
	"ToLatitude"	TEXT NOT NULL,
	"ToLongitude"	TEXT NOT NULL,
	"DrivingDistanceKM"	TEXT NOT NULL DEFAULT '0',
	"AverageSpeedKMH"	TEXT NOT NULL DEFAULT '0',
	"StatisticsSampleCount"	INTEGER NOT NULL DEFAULT 0,
	"HourOfDay"	INTEGER NOT NULL DEFAULT 12
);
CREATE TABLE IF NOT EXISTS "StopList" (
	"OperatorId"	TEXT,
	"OpenDataStopId"	TEXT,
	"AnnouncementShortEng"	TEXT NOT NULL,
	"AnnouncementShortChi"	TEXT NOT NULL,
	"AnnouncementLongEng"	TEXT,
	"AnnouncementLongChi"	TEXT,
	"AudioFileName"	TEXT,
	"LedFileName"	TEXT,
	"ArrivalLedFileName"	TEXT,
	"Latitude"	TEXT,
	"Longitude"	TEXT,
	"ArrivalDistanceOverride"	TEXT,
	UNIQUE("OperatorId","OpenDataStopId")
);
CREATE TABLE IF NOT EXISTS "RouteListOverride" (
	"RouteOperator"	TEXT NOT NULL,
	"OpenDataRouteId"	TEXT NOT NULL,
	"RouteDestEng"	TEXT,
	"RouteDestChi"	TEXT,
	"RouteTypeEng"	TEXT,
	"RouteTypeChi"	TEXT,
	"RouteViaChi"	TEXT,
	"RouteViaEng"	TEXT,
	"RouteEraNum"	INTEGER,
	UNIQUE("RouteOperator","OpenDataRouteId")
);
CREATE TABLE IF NOT EXISTS "StopListOverride" (
	"OperatorId"	TEXT NOT NULL,
	"OpenDataStopId"	TEXT NOT NULL,
	"AnnouncementShortEng"	TEXT,
	"AnnouncementShortChi"	TEXT,
	"AnnouncementLongEng"	TEXT,
	"AnnouncementLongChi"	TEXT,
	"AudioFileName"	TEXT,
	"LedFileName"	TEXT,
	"ArrivalLedFileName"	TEXT,
	"Latitude"	TEXT,
	"Longitude"	TEXT,
	"ArrivalDistanceOverride"	TEXT,
	UNIQUE("OperatorId","OpenDataStopId")
);
CREATE TABLE IF NOT EXISTS "BusStopGroups" (
	"BusStopGroupId"	TEXT NOT NULL,
	"MapOperatorId"	TEXT NOT NULL,
	"MapStopId"	TEXT NOT NULL,
	"Bound"	TEXT NOT NULL,
	UNIQUE("BusStopGroupId","MapOperatorId","MapStopId","Bound")
);
CREATE TABLE IF NOT EXISTS "RouteStopList" (
	"RouteCode"	INTEGER NOT NULL,
	"StopSeq"	INTEGER NOT NULL,
	"AnnouncementType"	TEXT NOT NULL DEFAULT '',
	"ShortEng"	TEXT,
	"ShortChi"	TEXT,
	"LongEng"	TEXT,
	"LongChi"	TEXT,
	"AudioFile"	TEXT,
	"LedFile"	TEXT,
	"TsdFile"	TEXT,
	"Latitude"	TEXT,
	"Longitude"	TEXT,
	"SpaNums"	TEXT,
	"MapOperatorId"	TEXT,
	"MapStopId"	TEXT,
	"OpenDataStopSeq"	INTEGER,
	"ArrivalDistanceOverride"	TEXT,
	"IsCircularPoint"	INTEGER NOT NULL DEFAULT 0,
	UNIQUE("RouteCode","StopSeq")
);
CREATE TABLE IF NOT EXISTS "SpecialAnnouncementList" (
	"SpecialAnnouncementNumber"	INTEGER NOT NULL UNIQUE,
	"AnnouncementType"	TEXT NOT NULL,
	"ShortEng"	TEXT NOT NULL,
	"ShortChi"	TEXT NOT NULL,
	"AudioFile"	TEXT,
	"LedFile"	TEXT
);
COMMIT;
